<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue';
import { csvText,localDate,moduleFor,validateRecord,summarizeRecords } from '@teacher-logbook/shared';
import type { Field,PageDefinition } from '@teacher-logbook/shared';
import type { BusinessRecord,RecordValues,Resource } from '@teacher-logbook/api-client';
import { api,state,studentName,references,errorMessage,confirm } from '../lib/workspace';
import { shareText } from '../lib/files';
const props=defineProps<{page:PageDefinition}>();const module=moduleFor(props.page.resource!);const resource=module.resource as Resource;
const rows=ref<BusinessRecord[]>([]);const total=ref(0);const pageNumber=ref(1);const keyword=ref('');const error=ref('');const busy=ref(false);const editing=ref(false);const editId=ref('');const form=reactive<RecordValues>({});const errors=ref<Record<string,string>>({});const schedule=ref(props.page.mode==='schedule');const selectedExam=ref('');
const dateFrom=ref('');const dateTo=ref('');const status=ref('');const statuses=['全部状态',...(module.fields.find(field=>field.key==='status')?.options??[])];
function query(){return {...props.page.filters,keyword:keyword.value,dateFrom:dateFrom.value,dateTo:dateTo.value,status:status.value};}
const weekdays=['周一','周二','周三','周四','周五','周六','周日'];
const filtered=computed(()=>selectedExam.value?rows.value.filter(row=>row.name===selectedExam.value):rows.value);
const metrics=computed(()=>summarizeRecords(resource,filtered.value));
const exams=computed(()=>['全部考试',...new Set(rows.value.map(row=>String(row.name)))]);
function choices(field:Field){return field.kind==='student'?state.students.map(row=>({value:row.id,label:String(row.name)+' · '+row.id.slice(0,6)})):field.kind==='role'?state.roles.map(row=>({value:row.id,label:String(row.role)})):(field.options??[]).map(value=>({value,label:value}));}
function label(row:RecordValues,field:Field){if(field.kind==='student')return studentName(row[field.key]);if(field.kind==='role')return String(state.roles.find(item=>item.id===row[field.key])?.role??'');return String(row[field.key]??'');}
function pickerValue(field:Field){return choices(field).find(item=>item.value===form[field.key])?.label??'请选择';}
function updateText(key:string,event:unknown){form[key]=(event as {detail:{value:string}}).detail.value;}
function pick(field:Field,index:string|number){form[field.key]=choices(field)[Number(index)]?.value??'';}
async function load(){busy.value=true;error.value='';try{const filters=query();if(props.page.mode==='summary'||schedule.value){rows.value=await api.allRecords(state.classId,resource,filters);total.value=rows.value.length;}else{const result=await api.listRecords(state.classId,resource,{...filters,page:pageNumber.value,pageSize:20});rows.value=result.items;total.value=result.total;}}catch(cause){error.value=errorMessage(cause);}finally{busy.value=false;}}
function edit(row?:BusinessRecord){for(const key of Object.keys(form))delete form[key];for(const field of module.fields)form[field.key]=row?.[field.key]??props.page.filters?.[field.key]??(field.kind==='date'?localDate():field.kind==='number'?0:field.options?.[0]??'');editId.value=row?.id??'';errors.value={};editing.value=true;}
async function save(){errors.value=validateRecord(module,form);if(Object.keys(errors.value).length||busy.value)return;busy.value=true;error.value='';try{const values=Object.fromEntries(module.fields.map(field=>[field.key,form[field.key]===''&&!field.required?null:field.kind==='number'?Number(form[field.key]):form[field.key]??null]));await api.saveRecord(state.classId,resource,values,editId.value||undefined);editing.value=false;if(['students','committee-roles'].includes(resource))await references();await load();}catch(cause){error.value=errorMessage(cause);}finally{busy.value=false;}}
async function remove(row:BusinessRecord){if(busy.value||!await confirm('删除记录','确认删除该记录？'))return;busy.value=true;try{await api.removeRecord(state.classId,resource,row.id);if(rows.value.length===1&&pageNumber.value>1)pageNumber.value--;if(['students','committee-roles'].includes(resource))await references();await load();}catch(cause){error.value=errorMessage(cause);}finally{busy.value=false;}}
async function toggle(row:BusinessRecord){busy.value=true;try{await api.saveRecord(state.classId,resource,{status:row.status==='已完成'?'待完成':'已完成'},row.id);await load();}catch(cause){error.value=errorMessage(cause);}finally{busy.value=false;}}
async function exportRows(){busy.value=true;try{const data=await api.allRecords(state.classId,resource,query());await shareText(csvText(module.fields.map(field=>field.label),data.map(row=>module.fields.map(field=>label(row,field)))),props.page.name+'.csv');}catch(cause){error.value=errorMessage(cause);}finally{busy.value=false;}}
async function changePage(step:number){pageNumber.value+=step;await load();}onMounted(load);
</script>
<template><view><view class="mini-row"><input v-model="keyword" placeholder="搜索记录" @confirm="pageNumber=1;load()"/><button size="mini" :loading="busy" @click="pageNumber=1;load()">查询</button></view><view class="mini-row"><picker v-if="statuses.length>1" :range="statuses" @change="status=Number($event.detail.value)===0?'':statuses[Number($event.detail.value)]??''"><view class="mini-picker">{{ status||'全部状态' }}</view></picker><template v-if="module.fields.some(field=>field.key==='date')"><picker mode="date" :value="dateFrom" @change="dateFrom=$event.detail.value"><view class="mini-picker">{{ dateFrom||'开始日期' }}</view></picker><picker mode="date" :value="dateTo" @change="dateTo=$event.detail.value"><view class="mini-picker">{{ dateTo||'结束日期' }}</view></picker><button v-if="dateFrom||dateTo" size="mini" @click="dateFrom='';dateTo=''">清除日期</button></template></view><view class="mini-row"><button class="primary" :disabled="busy" @click="edit()">新增</button><button :disabled="busy" @click="exportRows">导出</button><button v-if="resource==='courses'" @click="schedule=!schedule;load()">{{ schedule?'列表':'周课表' }}</button></view><text v-if="error" class="mini-error">{{ error }}</text><picker v-if="props.page.mode==='summary'&&resource==='exams'" :range="exams" @change="selectedExam=Number($event.detail.value)===0?'':exams[Number($event.detail.value)]??''"><view class="mini-picker">{{ selectedExam||'全部考试' }}</view></picker><view v-if="props.page.mode==='summary'" class="mini-metrics"><view v-for="metric in metrics" :key="metric[0]"><text>{{ metric[0] }}</text><text class="mini-number">{{ metric[1] }}</text></view></view><template v-if="schedule"><view v-for="day in weekdays" :key="day" class="mini-section"><text class="mini-title">{{ day }}</text><text v-if="!rows.some(row=>row.day===day)" class="mini-caption">暂无课程</text><view v-for="row in rows.filter(item=>item.day===day).sort((left,right)=>String(left.startTime).localeCompare(String(right.startTime)))" :key="row.id" class="mini-record" @click="edit(row)"><text class="mini-record-title">{{ row.course }} · {{ row.teacher }}</text><text>{{ String(row.startTime).slice(0,5) }} - {{ String(row.endTime).slice(0,5) }}</text></view></view></template><template v-else><view v-for="row in filtered" :key="row.id" class="mini-record"><view v-for="field in module.fields" :key="field.key" class="mini-detail"><text>{{ field.label }}</text><text selectable>{{ label(row,field) }}</text></view><view v-if="resource==='committee-members'" class="mini-detail"><text>职责</text><text>{{ state.roles.find(role=>role.id===row.roleId)?.duty }}</text></view><view class="mini-row"><button v-if="resource==='todos'" size="mini" :disabled="busy" @click="toggle(row)">{{ row.status==='已完成'?'重开':'完成' }}</button><button size="mini" :disabled="busy" @click="edit(row)">编辑</button><button size="mini" :disabled="busy" @click="remove(row)">删除</button></view></view><view v-if="!filtered.length&&!busy" class="mini-empty">暂无记录</view></template><view v-if="props.page.mode!=='summary'&&!schedule" class="mini-row"><button :disabled="busy||pageNumber===1" @click="changePage(-1)">上一页</button><text>{{ pageNumber }} / {{ Math.max(1,Math.ceil(total/20)) }}</text><button :disabled="busy||pageNumber*20>=total" @click="changePage(1)">下一页</button></view><view v-if="editing" class="mini-dialog"><text class="mini-title">{{ editId?'编辑':'新增' }} · {{ module.name }}</text><scroll-view scroll-y class="dialog-fields"><view v-for="field in module.fields" :key="field.key"><text class="mini-label">{{ field.label }}{{ field.required?' *':'' }}</text><picker v-if="['select','student','role'].includes(field.kind)" :range="choices(field)" range-key="label" @change="pick(field,$event.detail.value)"><view class="mini-picker">{{ pickerValue(field) }}</view></picker><picker v-else-if="field.kind==='date'||field.kind==='time'" :mode="field.kind" :value="String(form[field.key]??'')" @change="form[field.key]=$event.detail.value"><view class="mini-picker">{{ form[field.key]||'请选择' }}</view></picker><textarea v-else-if="field.kind==='textarea'" :value="String(form[field.key]??'')" @input="updateText(field.key,$event)" :disabled="busy" :maxlength="5000"/><input v-else v-model="form[field.key]" :type="['money','number'].includes(field.kind)?'digit':'text'" :disabled="busy"/><text v-if="errors[field.key]" class="mini-error">{{ errors[field.key] }}</text></view><text v-if="error" class="mini-error">{{ error }}</text></scroll-view><view class="mini-row"><button :disabled="busy" @click="editing=false">取消</button><button class="primary" :loading="busy" @click="save">保存</button></view></view></view></template>
